script:
$b64 = "b2Nfc2tfZDEyMGNiYTg1YWQzX25XZXo4cHJzXy00VjFuR1pZR3I0M29LNXdxWGQyX2oz"
$key = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))
"ZEN_API_KEY=$key" | Out-File -FilePath "C:\Users\E\AppData\Local\hermes\.env" -Encoding utf8
"Key written to .env"
$env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
$job = Start-Job -ScriptBlock {
  $env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
  hermes -z "Say HI" -m "space-bunny-free" --provider zen 2>&1 | Select-Object -First 10
}
if (Wait-Job $job -Timeout 60) {
  Receive-Job $job | Select-Object -First 10
} else {
  "TIMED OUT"
  Stop-Job $job
}
Remove-Job $job -Force
